-- Maybe NTS is simpler than I think - just the average trust score
SELECT ROUND(CAST(AVG((risk_profile->'risk_scores'->>'trust_score')::float) AS numeric), 4) as avg_trust
FROM risk_and_moderation;

-- Check if bot_likelihood is 0-100 scale
SELECT behavioral_anomaly_scores->'automation_spam'->>'bot_likelihood' as bl 
FROM behavioral_scores LIMIT 5;
